UPDATE plan SET status = 'ENDED', ended_on = #{endedOn}, updated_at = now()
WHERE status <> 'ENDED'
  AND id IN #{id}

UPDATE monthly_pick SET exposed = FALSE
WHERE exposed
  AND plan_id IN #{id}

